std::atomic<int> counter{0};
int main() {
  auto work = [] {
    for (int i = 0; i < 1000; ++i)
      counter = counter + 4;
  };
  std::thread t1(work), t2(work);
  t1.join(); t2.join();
  std::cout << counter << '\n';
}

