std::atomic<long> hits{0};
static_assert(
    std::atomic<long>::is_always_lock_free);

void worker() {   // run on 8 threads
    for (int i = 0; i < 10'000'000; ++i)
        hits.fetch_add(1,
            std::memory_order_relaxed);
}

